import { workflowServiceToken } from '@nocobase/app-plugin-workflow/server';

if (!app.container.has(workflowServiceToken)) {
  throw new Error('Workflow service is not configured.');
}
const workflowRuntime = app.container.resolve(workflowServiceToken);
const receipt = await workflowRuntime.trigger(
  'quotation-decision',
  { quotationId: 'Q-100', amount: 150000 },
  { eventKey: 'quotation-submitted:Q-100' },
);
if (receipt.status === 'skipped') {
  return receipt; // caller handles the runtime result; do not poll for a run
}
const { eventKey, runId } = receipt;
```

`workflowRuntime.trigger(key, input, options?)`:

- Resolves the workflow by stable key at runtime.
- May return a `skipped` receipt. It has no `eventKey` and creates no run to poll; handle the receipt after calling rather than pre-filtering DSL keys through runtime management state.
- Requires a JSON object and validates it against the `inputSchema` declared by the selected DSL package's `workflow.ts`. Read and obey that schema before writing the trigger call; `input` is not the workflow's administrator `parameters` object.
- Rejects input over 65,536 UTF-8 bytes.
- Resolves administrator defaults/overrides into an immutable run input snapshot.
- Accepts optional `eventKey` and `parentRunId`; parent linkage is used for nested calls and stack-limit checks.
- Creates the Workflow Run and enqueues work before returning `{ status: 'accepted', eventKey, runId }` in the ordinary path; execution continues asynchronously. `runId` is the stable execution reference for status queries and integrations such as Scheduler.
- Uses event key for invocation deduplication. Reusing it must represent the same business event. If a run already exists, another trigger with that key does not execute it again; reuse is appropriate when the caller does not know whether the original submission was accepted, not as a rerun mechanism for a confirmed failure.

export function defineWorkflowRuns(collection) {
    collection.bigInt('id').primary().autoIncrement().notNull();
    collection
        .belongsTo('workflow', WORKFLOW_COLLECTIONS.workflows)
        .targetKey('id')
        .foreignKey('workflowId')
        .foreignKeyType('bigInt')
        .notNull()
        .constraints(false);
    collection.string('workflowKey').notNull();
    collection.string('hash');
    collection.string('eventKey').notNull().unique({ mode: 'index' });
    collection
        .hasMany('nodeRuns', WORKFLOW_COLLECTIONS.nodeRuns)
        .sourceKey('id')
        .foreignKey('workflowRunId')
        .onDelete('cascade');
    collection.json('input').notNull().defaultTo({});
    collection.json('parameters').notNull().defaultTo({});
    collection.integer('status');
    collection.boolean('dispatched').notNull().defaultTo(false);
    collection.bigInt('parentRunId');
    collection.json('stack');
    collection.json('output');
    // These are instants, not wall clocks, so they are `datetimeTz`: it is the
    // only logical type whose value survives a driver that decodes timestamps
    // itself. The Repository is what applies that per dialect — see
    // `server/collections/store.ts`.
    collection.datetimeTz('startedAt');
    collection.datetimeTz('finishedAt');
    collection.datetimeTz('expiresAt');
    collection.datetimeTz('createdAt').notNull();
    collection.boolean('manually').notNull().defaultTo(false);
    collection.string('reason');
    collection.string('sourceType');
    collection.string('sourceId');
    collection.index(['dispatched', 'id']);
    collection.index(['status', 'expiresAt']);
    collection.index(['parentRunId', 'status']);
    collection.index(['sourceType', 'sourceId']);
}

export function defineWorkflowNodeRuns(collection) {
    collection.bigInt('id').primary().autoIncrement().notNull();
    collection
        .belongsTo('workflowRun', WORKFLOW_COLLECTIONS.runs)
        .targetKey('id')
        .foreignKey('workflowRunId')
        .foreignKeyType('bigInt')
        .notNull()
        .constraints(false)
        .onDelete('cascade');
    collection
        .belongsTo('node', WORKFLOW_COLLECTIONS.nodes)
        .targetKey('id')
        .foreignKey('nodeId')
        .foreignKeyType('bigInt')
        .notNull()
        .constraints(false);
    collection.string('nodeKey').notNull();
    collection.integer('status').notNull();
    collection.json('meta');
    collection.json('result');
    collection.text('error');
    // These are instants, not wall clocks, so they are `datetimeTz`: it is the
    // only logical type whose value survives a driver that decodes timestamps
    // itself. The Repository is what applies that per dialect — see
    // `server/collections/store.ts`.
    collection.datetimeTz('startedAt').notNull();
    collection.datetimeTz('finishedAt');
    collection.datetimeTz('expiresAt');
    collection.text('log');
    collection.index(['workflowRun', 'id']);
}

