export async function finalizeWorkflowRun(options) {
    const finishedAt = options.finishedAt ?? nowInstant();
    const result = await options.store.runs.updateMany({
        filter: {
            id: asIdFilter(options.runId),
            status: options.expectedStatus,
        },
        values: {
            status: options.status,
            output: serializeJson(options.output),
            reason: options.reason,
            finishedAt,
        },
    });
    if (result.updatedCount === 0)
        return null;
    const row = await options.store.runs.findOne({
        filter: { id: asIdFilter(options.runId) },
        select: (select) => select.fields('sourceType', 'sourceId'),
    });
    const event = {
        runId: options.runId,
        status: options.status,
        reason: options.reason,
        output: options.output,
        finishedAt,
        sourceType: typeof row?.sourceType === 'string' ? row.sourceType : null,
        sourceId: typeof row?.sourceId === 'string' ? row.sourceId : null,
    };
    if (options.status !== 0) {
        try {
            await options.observer?.(event);
        }
        catch (error) {
            // The authoritative Workflow terminal state must survive an optional
            // projection observer being temporarily unavailable. Scheduler repairs
            // a missed fast-path notification through its persisted observer.
            options.logger?.error('Workflow terminal observer failed', {
                runId: options.runId,
                sourceType: event.sourceType,
                sourceId: event.sourceId,
                error,
            });
        }
    }
    return event;
}

async send(input) {
    this.activate();
    validateNotificationIdempotencyKey(input.idempotencyKey);
    if (input.source !== undefined &&
        (!input.source ||
            typeof input.source.type !== 'string' ||
            !input.source.type.trim() ||
            (input.source.referenceId !== undefined &&
                typeof input.source.referenceId !== 'string')))
        throw new Error('Notification source requires a type and an optional string referenceId.');
    if (!input.messages ||
        typeof input.messages !== 'object' ||
        Array.isArray(input.messages))
        throw new Error('Notification messages must be a Channel-to-message map.');
    for (const key of [
        'to',
        'channels',
        'content',
        'routing',
        'channelOverrides',
    ])
        if (key in input)
            throw new Error(`Unsupported notification send property "${key}".`);
    const channels = Object.keys(input.messages);
    if (channels.length === 0)
        throw new Error('At least one notification message is required.');
    const message = {};
    const expandedRecipients = [];
    for (const channel of channels) {
        await this.ensureRuntime(channel);
        const validated = this.channelManager.validateMessage(channel, input.messages[channel]);
        message[channel] = validated.message;
        const [provider] = this.channelManager.providerIdentities(channel);
        for (const recipient of validated.recipients)
            expandedRecipients.push({
                channels: [{ channel, provider, recipient }],
            });
    }
    const requestFingerprint = notificationRequestFingerprint({
        ...input,
        messages: message,
    });
    const existing = await this.store.getLogByIdempotencyKey(input.idempotencyKey);
    if (existing) {
        if (existing.requestFingerprint !== requestFingerprint) {
            throw new NotificationIdempotencyConflictError(input.idempotencyKey);
        }
        const existingDeliveries = await this.store.listDeliveries(existing.id);
        await Promise.all(existingDeliveries
            .filter((delivery) => delivery.status === 'pending')
            .map(async (delivery) => this.dispatch(delivery.id)));
        const snapshot = await this.statusSnapshot(existing);
        return {
            notificationId: snapshot.notificationId,
            idempotencyKey: input.idempotencyKey,
            deduplicated: true,
            status: snapshot.status,
            deliveries: snapshot.deliveries,
        };
    }
    return this.sendExpanded({
        idempotencyKey: input.idempotencyKey,
        requestFingerprint,
        source: input.source,
        recipients: expandedRecipients,
        message,
    });

