        store,
        async recipientExists(userId) {
            return Boolean(await users.get(userId));
        },
    }));
}

export async function fetchInbox(client, filters, signal) {
    const query = new URLSearchParams({ limit: String(filters.limit ?? 25) });
    if (filters.unreadOnly)
        query.set('unreadOnly', 'true');
    if (filters.cursor)
        query.set('cursor', filters.cursor);
    const value = await client.request({
        path: `notifications/in-app?${query}`,
        signal,
    });
    if (Array.isArray(value))
        return { data: value };
    if (isRecord(value) && Array.isArray(value.data)) {
        return {
            data: value.data,
            nextCursor: typeof value.nextCursor === 'string' ? value.nextCursor : undefined,
        };
    }
    throw new Error('Inbox returned an invalid response.');
}
